text:
ion: send
    channel: { $ref: '#/channels/eodCompleted' }
    messages:
      - $ref: '#/channels/eodCompleted/messages/eodCompleted'
components:
  messages:
    TransferStatusChanged:
      name: TransferStatusChanged
      payload: { $ref: '#/components/schemas/TransferStatusChanged' }
    TransferReversed:
      name: TransferReversed
      payload: { $ref: '#/components/schemas/TransferReversed' }
    LoanStatusChanged:
      name: LoanStatusChanged
      payload: { $ref: '#/components/schemas/LoanStatusChanged' }
    ClearingCallbackReceived:
      name: ClearingCallbackReceived
      payload: { $ref: '#/components/schemas/ClearingCallbackReceived' }
    EodCompleted:
      name: EodCompleted
      payload: { $ref: '#/components/schemas/EodCompleted' }
  schemas:
    TransferStatusChanged:
      type: object
      required: [eventId, eventType, occurredAt, transferId, status]
      properties:
        eventId: { type: string, minLength: 1, maxLength: 128 }
        eventType: { const: transfer.status.changed }
        occurredAt: { type: string, format: date-time }
        transferId: { type: string, minLength: 1, maxLength: 64 }
        status: { type: string, enum: [CREATED, VALIDATING, RISK_REVIEW, PENDING_APPROVAL, PENDING_CORE_POSTING, PENDING_CLEARING, SETTLED, FAILED, TIMED_OUT, RETURNED, REVERSAL_PENDING, REVERSED] }
        coreReference: { type: [string, 'null'] }
        correlationId: { type: [string, 'null'] }
    TransferReversed:
      type: object
      required: [eventId, eventType, occurredAt, transferId, status]
      properties:
        eventId: { type: string }
        eventType: { const: transfer.reversed }
        occurredAt: { type: string, format: date-time }
        transferId: { type: string }
        status: { const: REVERSED }
        c
oreReference: { type: string }
    LoanStatusChanged:
      type: object
      required: [eventId, eventType, occurredAt, applicationId, status]
      properties:
        eventId: { type: string }
        eventType: { const: loan.status.changed }
        occurredAt: { type: string, format: date-time }
        applicationId: { type: string, format: uuid }
        status: { type: string, enum: [DRAFT, SUBMITTED, SCORED, APPROVED, DISBURSED, CLOSED, REJECTED] }
        coreLoanId: { type: [integer, 'null'] }
    ClearingCallbackReceived:
      type: object
      required: [eventId, eventType, occurredAt, clearingId, status]
      properties:
        eventId: { type: string }
        eventType: { const: clearing.callback.received }
        occurredAt: { type: string, format: date-time }
        clearingId: { type: string, format: uuid }
        status: { type: string, enum: [SETTLED, TIMED_OUT, RETURNED, DUPLICATE_IGNORED] }
        sequence: { type: integer }
    EodCompleted:
      type: object
      required: [eventId, eventType, occurredAt, businessDate, status]
      properties:
        eventId: { type: string }
        eventType: { const: eod.completed }
        occurredAt: { type: string, format: date-time }
        businessDate: { type: string, format: date }
        status: { type: string, enum: [COMPLETED, FAILED] }
        reconciliationStatus: { type: string, enum: [MATCHED, DIFFERENCE, BLOCKED] }
